import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Chart Trading Terminal","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/trading-terminal.md","filePath":"new-features/trading-terminal.md"}'),n={name:"new-features/trading-terminal.md"};function o(d,e,s,l,c,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="chart-trading-terminal" tabindex="-1">Chart Trading Terminal <a class="header-anchor" href="#chart-trading-terminal" aria-label="Permalink to &quot;Chart Trading Terminal&quot;">​</a></h1><p>The <code>/trading</code> route is Tradeboard&#39;s multi-chart trading workspace. It combines historical and live market data, chart analysis, drawings, market depth, and order entry in one React interface.</p><h2 id="layouts-and-state" tabindex="-1">Layouts and State <a class="header-anchor" href="#layouts-and-state" aria-label="Permalink to &quot;Layouts and State&quot;">​</a></h2><p>Seven persisted layouts are available:</p><ul><li>one chart;</li><li>two charts side by side;</li><li>two charts stacked;</li><li>a three-chart <code>1 + 2</code> layout with one large pane;</li><li>a <code>2×2</code> four-chart grid;</li><li>a six-chart <code>3×2</code> grid;</li><li>an eight-chart <code>4×2</code> grid.</li></ul><p>Each pane retains its own symbol and chart state. Layout choice and supported chart preferences persist in the browser or application preference store so returning to the terminal restores the workspace.</p><h2 id="charts-and-history" tabindex="-1">Charts and History <a class="header-anchor" href="#charts-and-history" aria-label="Permalink to &quot;Charts and History&quot;">​</a></h2><p>The terminal supports candles, bars, line/area variants, Heikin Ashi, Renko, Range Bars, and Line Break views. Scrolling to the left edge requests older history so analysis is not limited to the initial window.</p><p>Indicators are loaded from the chart library catalog. Multiple instances can be added and configured per pane. Volume and grid display can be adjusted independently from the primary price scale.</p><h2 id="drawing-tools" tabindex="-1">Drawing Tools <a class="header-anchor" href="#drawing-tools" aria-label="Permalink to &quot;Drawing Tools&quot;">​</a></h2><p>One drawing rail controls the active pane and includes line, channel, Fibonacci/Gann, shape, cycle, forecast, measurement, and text tools. Drawings support styling, locking, magnet mode, undo/redo, and per-pane persistence.</p><p>The shared rail deliberately targets only the active pane. Confirm the highlighted pane before adding, editing, or removing a drawing in a multi-chart layout.</p><h2 id="symbols-market-data-and-orders" tabindex="-1">Symbols, Market Data, and Orders <a class="header-anchor" href="#symbols-market-data-and-orders" aria-label="Permalink to &quot;Symbols, Market Data, and Orders&quot;">​</a></h2><p>Symbol search is ranked and debounced and can be opened independently for every pane. The terminal receives live ticks from Tradeboard&#39;s raw WebSocket proxy, with REST quote fallback where required. The same market-data manager is shared across the page rather than opening one Gunicorn request thread per chart.</p><p>The order dialog supports inline order entry and market-depth review. Account-level order updates arrive through the order-update stream when the active broker provides a push adapter; Groww uses the server&#39;s explicit orderbook-polling fallback.</p><h2 id="operational-boundaries" tabindex="-1">Operational Boundaries <a class="header-anchor" href="#operational-boundaries" aria-label="Permalink to &quot;Operational Boundaries&quot;">​</a></h2><ul><li>Historical range, live fields, depth levels, and order-update latency depend on the active broker and account entitlement.</li><li>Market data uses the raw WebSocket proxy on port <code>8765</code> (normally exposed as <code>/ws</code> behind the production reverse proxy); it is separate from Flask-SocketIO application events.</li><li>A displayed quote or analytical drawing is not a guarantee of execution price.</li><li>Test order entry in Analyzer mode before using the terminal with live capital.</li></ul><p>See <a href="./../api-documentation/v1/websockets">WebSocket API</a> for the underlying market-data and order-update protocol.</p>',18)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
